        ("CSS Debugging", "CSS Outline for Layout Debugging", "Why is outline: 1px solid red preferred over border: 1px solid red for debugging overflowing elements?", "outlines do not take up layout space or alter element dimensions, so debugging lines won't accidentally cause new layout wrapping.", "Easy", "Debugging", "* { outline: 1px solid red !important; }", "What tool highlights layout shifts automatically?"),
        ("CSS Debugging", "Horizontal Scrollbar Bug", "What is the most common cause of an unwanted horizontal scrollbar on mobile websites?", "An element with fixed width (width: 500px), unconstrained images, or negative margins extending wider than the 100vw viewport.", "Easy", "Debugging", "img { max-width: 100%; }\nbody { overflow-x: hidden; }", "How do you find which element overflows using DevTools?"),
        ("CSS Debugging", "Finding Overflow Element via Console", "How do you find the exact element causing horizontal overflow via the browser console?", "Run: document.querySelectorAll('*').forEach(el => { if (el.offsetWidth > document.documentElement.offsetWidth) console.log(el); });.", "Intermediate", "Debugging", "document.querySelectorAll('*').forEach(el => {\n  if (el.offsetWidth > document.documentElement.offsetWidth) console.log(el);\n});", "What does offsetWidth measure?"),
        ("CSS Debugging", "Specificity Battle Bug", "Why did a style rule written later in the CSS file fail to apply over an earlier rule?", "Because the earlier rule had higher specificity (e.g. #id vs .class). Source order only matters when specificity is exactly equal.", "Intermediate", "Debugging", "", "How does DevTools show overwritten styles?"),
        ("CSS Debugging", "Broken Flex Child Sizing", "Why does an image inside a flex container stretch and distort when flex-direction is row?", "Because align-items: stretch is the default. Add align-self: flex-start or height: auto to preserve natural aspect ratio.", "Easy", "Debugging", "img { align-self: center; height: auto; }", "What does object-fit do to prevent distortion?"),
        ("CSS Debugging", "Collapsing Height with Position Absolute", "Why did a parent container collapse to 0 height after adding position: absolute to its children?", "Absolute elements are removed from normal document flow. The parent no longer sees any in-flow height from absolute children.", "Easy", "Debugging", "", "How do you give the parent height?"),
